  1→import type { RawDevEvent, NormalizedDevEvent } from "../adapters/types.js";
  2→
  3→// Tools that modify state — their tool_call events are categorized as "action"
  4→const STATE_MODIFYING_TOOLS = new Set([
  5→  "Edit",
  6→  "Write",
  7→  "Bash",
  8→  "NotebookEdit",
  9→]);
 10→
 11→// Tools that read state — their tool_call events are categorized as "reflection"
 12→// (Read, Glob, Grep, Agent, Explore, WebSearch, WebFetch, etc.)
 13→
 14→/**
 15→ * Normalize a sequence of RawDevEvents into NormalizedDevEvents.
 16→ *
 17→ * Assigns causal order, classifies each event into a semantic category,
 18→ * extracts content summaries, and filters out events with no meaningful content.
 19→ */
 20→export function normalize(
 21→  events: RawDevEvent[],
 22→  sessionId: string,
 23→): NormalizedDevEvent[] {
 24→  const result: NormalizedDevEvent[] = [];
 25→  let causalOrder = 0;
 26→
 27→  for (let i = 0; i < events.length; i++) {
 28→    const event = events[i];
 29→    const extracted = extractContent(event);
 30→
 31→    // Filter out events with no meaningful content
 32→    if (!extracted) continue;
 33→
 34→    const { category, actor } = classify(event, events, i);
 35→
 36→    result.push({
 37→      id: `${sessionId}-${causalOrder}`,
 38→      sessionId,
 39→      timestamp: event.timestamp,
 40→      causalOrder,
 41→      category,
 42→      actor,
 43→      content: extracted,
 44→      rawEventId: event.id,
 45→    });
 46→
 47→    causalOrder++;
 48→  }
 49→
 50→  return result;
 51→}
 52→
 53→// ── Classification ───────────────────────────────────────────────────
 54→
 55→type Classification = {
 56→  category: NormalizedDevEvent["category"];
 57→  actor: NormalizedDevEvent["actor"];
 58→};
 59→
 60→function classify(
 61→  event: RawDevEvent,
 62→  events: RawDevEvent[],
 63→  index: number,
 64→): Classification {
 65→  switch (event.type) {
 66→    case "conversation_turn":
 67→      return { category: "intent", actor: "user" };
 68→
 69→    case "tool_result":
 70→      return { category: "result", actor: "user" };
 71→
 72→    case "tool_call":
 73→      return {
 74→        category: isStateModifying(event) ? "action" : "reflection",
 75→        actor: "ai",
 76→      };
 77→
 78→    case "ai_response":
 79→      return {
 80→        category: isAfterToolResult(events, index)
 81→          ? "reflection"
 82→          : "proposal",
 83→        actor: "ai",
 84→      };
 85→  }
 86→}
 87→
 88→/**
 89→ * Check whether a tool_call event uses a state-modifying tool.
 90→ */
 91→function isStateModifying(event: RawDevEvent): boolean {
 92→  const toolName = getToolName(event);
 93→  return toolName !== undefined && STATE_MODIFYING_TOOLS.has(toolName);
 94→}
 95→
 96→/**
 97→ * An ai_response is a "reflection" if the most recent non-ai_response event
 98→ * before it (scanning backwards) is a tool_result. Otherwise it's a "proposal".
 99→ */
100→function isAfterToolResult(events: RawDevEvent[], index: number): boolean {
101→  for (let j = index - 1; j >= 0; j--) {
102→    const prev = events[j];
103→    // Skip over other ai_response events in the same message
104→    if (prev.type === "ai_response") continue;
105→    return prev.type === "tool_result";
106→  }
107→  return false;
108→}
109→
110→// ── Content Extraction ───────────────────────────────────────────────
111→
112→function extractContent(
113→  event: RawDevEvent,
114→): NormalizedDevEvent["content"] | null {
115→  const raw = event.raw;
116→
117→  switch (event.type) {
118→    case "conversation_turn": {
119→      const text = getUserText(raw);
120→      if (!text) return null;
121→      return {
122→        summary: truncate(text, 200),
123→        detail: text,
124→      };
125→    }
126→
127→    case "ai_response": {
128→      const text = getAiText(event);
129→      if (!text) return null;
130→      return {
131→        summary: truncate(text, 200),
132→        detail: text,
133→      };
134→    }
135→
136→    case "tool_call": {
137→      const toolName = getToolName(event);
138→      const input = getToolInput(event);
139→      if (!toolName) return null;
140→
141→      const filePath = extractFilePath(input);
142→      const summary = filePath
143→        ? `Tool: ${toolName} on ${filePath}`
144→        : `Tool: ${toolName}`;
145→      const detail = input ? JSON.stringify(input) : summary;
146→      const filesAffected = filePath ? [filePath] : undefined;
147→
148→      return { summary: truncate(summary, 200), detail, filesAffected };
149→    }
150→
151→    case "tool_result": {
152→      const text = getToolResultText(raw);
153→      if (!text) return null;
154→      return {
155→        summary: truncate(text, 200),
156→        detail: text,
157→      };
158→    }
159→  }
160→}
161→
162→// ── Helpers ──────────────────────────────────────────────────────────
163→
164→function truncate(s: string, maxLen: number): string {
165→  return s.length <= maxLen ? s : s.slice(0, maxLen);
166→}
167→
168→/**
169→ * Extract user text from the raw log entry.
170→ * Content can be a string or an array of content blocks.
171→ */
172→function getUserText(raw: Record<string, unknown>): string | null {
173→  const msg = raw.message as { content?: unknown } | undefined;
174→  if (!msg?.content) return null;
175→  if (typeof msg.content === "string") return msg.content;
176→  return null;
177→}
178→
179→/**
180→ * Extract AI text from an ai_response event.
181→ * The event ID encodes which content block it came from (e.g., "a-001-text-1").
182→ */
183→function getAiText(event: RawDevEvent): string | null {
184→  const raw = event.raw;
185→  const msg = raw.message as { content?: unknown[] } | undefined;
186→  if (!msg?.content || !Array.isArray(msg.content)) return null;
187→
188→  // Find the text block index from the event ID (format: "...-text-N")
189→  const match = event.id.match(/-text-(\d+)$/);
190→  if (match) {
191→    const idx = parseInt(match[1], 10);
192→    const block = msg.content[idx] as { type?: string; text?: string } | undefined;
193→    if (block?.type === "text" && block.text) return block.text;
194→  }
195→
196→  // Fallback: find first text block
197→  for (const block of msg.content) {
198→    const b = block as { type?: string; text?: string };
199→    if (b.type === "text" && b.text) return b.text;
200→  }
201→  return null;
202→}
203→
204→/**
205→ * Extract tool name from a tool_call event.
206→ */
207→function getToolName(event: RawDevEvent): string | undefined {
208→  const raw = event.raw;
209→  const msg = raw.message as { content?: unknown[] } | undefined;
210→  if (!msg?.content || !Array.isArray(msg.content)) return undefined;
211→
212→  // Find tool_use block index from event ID (format: "...-tool-N")
213→  const match = event.id.match(/-tool-(\d+)$/);
214→  if (match) {
215→    const idx = parseInt(match[1], 10);
216→    const block = msg.content[idx] as { type?: string; name?: string } | undefined;
217→    if (block?.type === "tool_use" && block.name) return block.name;
218→  }
219→
220→  // Fallback: first tool_use block
221→  for (const block of msg.content) {
222→    const b = block as { type?: string; name?: string };
223→    if (b.type === "tool_use" && b.name) return b.name;
224→  }
225→  return undefined;
226→}
227→
228→/**
229→ * Extract tool input from a tool_call event.
230→ */
231→function getToolInput(
232→  event: RawDevEvent,
233→): Record<string, unknown> | undefined {
234→  const raw = event.raw;
235→  const msg = raw.message as { content?: unknown[] } | undefined;
236→  if (!msg?.content || !Array.isArray(msg.content)) return undefined;
237→
238→  const match = event.id.match(/-tool-(\d+)$/);
239→  if (match) {
240→    const idx = parseInt(match[1], 10);
241→    const block = msg.content[idx] as {
