243→      input?: Record<string, unknown>;
244→    } | undefined;
245→    if (block?.type === "tool_use" && block.input) return block.input;
246→  }
247→
248→  for (const block of msg.content) {
249→    const b = block as { type?: string; input?: Record<string, unknown> };
250→    if (b.type === "tool_use" && b.input) return b.input;
251→  }
