  1→import crypto from "node:crypto";
  2→import { parseClaudeCodeLog } from "../adapters/claude-code.js";
  3→import { normalize } from "./normalize.js";
  4→import { classifySession } from "./classify.js";
  5→import { chunkSession } from "./chunk.js";
  6→import { detectMoments } from "./moments.js";
  7→import { detectTransitionsAndOutcomes } from "./transitions.js";
  8→import { generateNarrative } from "./narrative.js";
  9→import { storeSessionDigest } from "../storage/queries.js";
 10→import type {
 11→  SessionNarrative,
 12→  SessionMoment,
 13→  IntentTransition,
 14→  AcceptedOutcome,
 15→} from "../adapters/types.js";
 16→
 17→function log(step: string): void {
 18→  process.stderr.write(`${step}\n`);
 19→}
 20→
 21→export async function runPipeline(logPath: string): Promise<{
 22→  sessionId: string;
 23→  narrative: SessionNarrative;
 24→  moments: SessionMoment[];
 25→  transitions: IntentTransition[];
 26→  outcomes: AcceptedOutcome[];
 27→}> {
 28→  // 1. Parse
 29→  log("[1/9] Parsing CC log...");
 30→  const rawEvents = await parseClaudeCodeLog(logPath);
 31→
 32→  // 2. Generate sessionId
 33→  const sessionId = crypto.randomUUID();
 34→
 35→  // 3. Normalize
 36→  log(`[2/9] Normalizing ${rawEvents.length} events...`);
 37→  const normalizedEvents = normalize(rawEvents, sessionId);
 38→
 39→  // Large session warning
 40→  if (normalizedEvents.length > 300) {
 41→    const estimatedChunks = Math.ceil(normalizedEvents.length / 60);
 42→    const estimatedLlmCalls = estimatedChunks + 3; // pass1 per chunk + classify + pass2 + transitions + narrative
 43→    log(
 44→      `  ⚠ Large session: ${normalizedEvents.length} events, ~${estimatedChunks} chunks, ~${estimatedLlmCalls} LLM calls`,
 45→    );
 46→  }
 47→
 48→  // 4. Classify
 49→  log("[3/9] Classifying session shape...");
 50→  const sessionShape = await classifySession(normalizedEvents);
 51→
 52→  // 5. Chunk
 53→  const sessionChunks = chunkSession(normalizedEvents, sessionId);
 54→  log(`[4/9] Chunking into ${sessionChunks.length} windows...`);
 55→
 56→  // 6. Detect moments (pass 1 + 2)
 57→  log("[5/9] Detecting moments (pass 1)...");
 58→  log("[6/9] Detecting moments (pass 2)...");
 59→  const sessionMoments = await detectMoments(sessionChunks, sessionShape);
 60→
 61→  // 7. Transitions + outcomes
 62→  log("[7/9] Detecting transitions & outcomes...");
 63→  const { transitions, outcomes } = await detectTransitionsAndOutcomes(
 64→    sessionMoments,
 65→    sessionId,
 66→  );
 67→
 68→  // 8. Narrative
 69→  log("[8/9] Generating narrative...");
 70→  const narrative = await generateNarrative(
 71→    sessionMoments,
 72→    transitions,
 73→    outcomes,
 74→    sessionShape,
 75→  );
 76→  narrative.sessionId = sessionId;
 77→
 78→  // 9. Store
 79→  log("[9/9] Storing to database...");
 80→
 81→  // Derive timestamps from raw events
 82→  const timestamps = rawEvents
 83→    .map((e) => e.timestamp)
 84→    .filter(Boolean)
 85→    .map((t) => new Date(t));
 86→  const startedAt = timestamps.length > 0 ? new Date(Math.min(...timestamps.map((d) => d.getTime()))) : null;
 87→  const endedAt = timestamps.length > 0 ? new Date(Math.max(...timestamps.map((d) => d.getTime()))) : null;
 88→
 89→  try {
 90→    await storeSessionDigest({
 91→      sessionId,
 92→      sourceType: "claude-code",
 93→      sourcePath: logPath,
 94→      sessionShape,
 95→      startedAt,
 96→      endedAt,
 97→      rawEvents,
 98→      normalizedEvents,
 99→      chunks: sessionChunks,
100→      moments: sessionMoments,
101→      transitions,
102→      outcomes,
103→      narrative,
104→    });
105→  } catch (err) {
106→    log(
107→      `  ⚠ Database write failed: ${err instanceof Error ? err.message : String(err)}`,
108→    );
109→    log("  Pipeline results are still available, just not persisted.");
110→  }
111→
112→  return {
113→    sessionId,
114→    narrative,
115→    moments: sessionMoments,
116→    transitions,
117→    outcomes,
118→  };
119→}
