 14→export function registerDigestCommand(program: Command): void {
 15→  program
 16→    .command("digest [path]")
 17→    .description("Ingest conversation logs and produce session digests")
 18→    .option("--last <n>", "Process N most recent sessions", parseInt)
 19→    .option("--dry-run", "Run deterministic pipeline only (no LLM calls), print stats")
 20→    .action(async (path: string | undefined, opts: { last?: number; dryRun?: boolean }) => {
 21→      try {
 22→        if (opts.dryRun) {
 23→          await runDryRun(path, opts.last);
 24→          return;
 25→        }
 26→
 27→        const paths = await resolvePaths(path, opts.last);
 28→
 29→        for (const logPath of paths) {
 30→          const result = await runPipeline(logPath);
 31→          printDigest(result);
 32→          if (paths.length > 1) {
 33→            console.log("\n" + "─".repeat(60) + "\n");
 34→          }
 35→        }
 36→      } catch (err) {
 37→        console.error(
 38→          `Error: ${err instanceof Error ? err.message : String(err)}`,
 39→        );
 40→        process.exit(1);
 41→      }
 42→    });
 43→}
 44→
 45→// ── Path Resolution ─────────────────────────────────────────────────
 46→
 47→async function resolvePaths(
 48→  path: string | undefined,
 49→  last: number | undefined,
 50→): Promise<string[]> {
 51→  if (path) {
 52→    return [path];
 53→  }
 54→
 55→  if (last && last > 0) {
 56→    const paths = await discoverLogs(last);
 57→    if (paths.length === 0) {
 58→      throw new Error("No Claude Code logs found in ~/.claude/projects/");
 59→    }
 60→    return paths;
 61→  }
 62→
 63→  // Default: latest log
 64→  const latest = await discoverLatestLog();
 65→  if (!latest) {
 66→    throw new Error(
 67→      "No Claude Code logs found in ~/.claude/projects/. Provide an explicit path.",
 68→    );
 69→  }
 70→  return [latest];
 71→}
 72→
 73→// ── Dry Run ─────────────────────────────────────────────────────────
 74→
