   286→/**
   287→ * Format events grouped by exchange (user intent + following AI events).
   288→ * Events not part of any exchange render as standalone.
   289→ */
   290→function formatThreadedEvents(events: NormalizedDevEvent[]): string {
   291→  // Find all intent (user message) indices
   292→  const intentIndices: number[] = [];
   293→  for (let i = 0; i < events.length; i++) {
   294→    if (events[i].category === "intent") {
   295→      intentIndices.push(i);
   296→    }
   297→  }
   298→
   299→  // If no intents, fall back to flat format
   300→  if (intentIndices.length === 0) {
   301→    return formatEventsFlat(events);
   302→  }
   303→
   304→  const blocks: string[] = [];
   305→
   306→  // Events before the first intent (standalone)
   307→  if (intentIndices[0] > 0) {
   308→    const standalone = events.slice(0, intentIndices[0]);
   309→    blocks.push(formatEventsFlat(standalone));
   310→  }
   311→
   312→  // Each exchange: intent + following AI events until next intent
   313→  for (let k = 0; k < intentIndices.length; k++) {
   314→    const devIdx = intentIndices[k];
   315→    const nextIntentIdx =
   316→      k + 1 < intentIndices.length ? intentIndices[k + 1] : events.length;
   317→
   318→    const devEvent = events[devIdx];
   319→    const aiEvents = events.slice(devIdx + 1, nextIntentIdx);
   320→
   321→    const devDetail = truncateDetail(devEvent.content.detail);
   322→
   323→    let block = `── Exchange ──\n[${devEvent.causalOrder}] DEV: "${devDetail}"`;
   324→
   325→    if (aiEvents.length > 0) {
   326→      block += "\n  AI:";
   327→      for (const ae of aiEvents) {
   328→        block += `\n    - ${formatAiEvent(ae)}`;
   329→      }
   330→    }
   331→
   332→    blocks.push(block);
   333→  }
   334→
   335→  return blocks.join("\n\n");
   336→}
   337→
   338→function formatAiEvent(e: NormalizedDevEvent): string {
   339→  const files = e.content.filesAffected ?? [];
   340→  const detail = truncateDetail(e.content.detail);
   341→
   342→  switch (e.category) {
   343→    case "proposal":
   344→    case "reflection":
   345→      return `[${e.causalOrder}] "${detail}"`;
   346→    case "action": {
   347→      // Extract tool name from summary (format: "Tool: Name on /path")
   348→      const toolMatch = e.content.summary.match(/^Tool:\s+(\S+)/);
   349→      const toolName = toolMatch?.[1] ?? "Action";
   350→      if (files.length > 0) {
   351→        return `[${e.causalOrder}] ${toolName} ${files[0]}`;
   352→      }
   353→      return `[${e.causalOrder}] ${toolName}`;
   354→    }
   355→    case "result":
   356→      return `[${e.causalOrder}] Result: ${truncateDetail(e.content.summary)}`;
   357→    default:
   358→      return `[${e.causalOrder}] ${detail}`;
   359→  }
   360→}
   361→
   362→function formatEventsFlat(events: NormalizedDevEvent[]): string {
   363→  return events
   364→    .map((e) => {
   365→      const actor = e.actor === "user" ? "DEV" : "AI";
   366→      const category = e.category.toUpperCase();
   367→      const files = e.content.filesAffected?.length
   368→        ? ` [${e.content.filesAffected.join(", ")}]`
   369→        : "";
   370→      const detail = truncateDetail(e.content.detail);
   371→      return `[${e.causalOrder}] ${actor}/${category}${files}: ${detail}`;
   372→    })
   373→    .join("\n\n");
   374→}
   375→
   376→function truncateDetail(text: string): string {
   377→  return text.length > 400 ? text.slice(0, 400) + "..." : text;
   378→}
