173→// ── Pass 2: Cross-Chunk Merge & Arc Assignment ───────────────────────
174→
175→export interface Pass2Input {
176→  pass1Moments: { chunkIndex: number; moments: Pass1Moment[] }[];
177→  sessionShape: SessionShape;
178→  totalChunks: number;
179→}
180→
181→export function buildPass2Prompt(input: Pass2Input): {
182→  system: string;
183→  user: string;
184→} {
185→  const { pass1Moments, sessionShape, totalChunks } = input;
186→
187→  const system = `You are an expert at synthesizing developer session moments into coherent arcs. You receive moments detected across multiple chunks of a single session and must:
188→
189→1. **Deduplicate** — If the same moment was detected in overlapping chunks, keep the best version (more specific statement, stronger evidence).
190→2. **Merge** — If two moments describe the same underlying event from different perspectives, merge them into one.
191→3. **Assign arcs** — Group related moments into narrative arcs. An arc is a thread of related activity (e.g., "setting up auth middleware" or "debugging the flaky test"). Give each arc a short kebab-case ID.
192→4. **Assign arc roles** — Within each arc, mark each moment's role:
193→   - **origin** — The moment that started this arc (first proposal, initial discovery)
194→   - **development** — Moments that advance the arc (execution, further proposals)
195→   - **turning_point** — Pivots, rejections, breakthroughs that change the arc's direction
196→   - **resolution** — The arc reaches a conclusion (commitment, final confirmation)
197→5. **Link related moments** — If moment N was caused by or responds to moment M, include M's index in relatedMomentIds. Use 0-based indices into YOUR output array.
198→
199→## Rules
200→
201→- Preserve the developer's own language in statements. Don't rewrite to be more "professional."
202→- If a moment from Pass 1 is low quality (vague statement, no real evidence), drop it.
203→- Don't invent moments that weren't in Pass 1. You can only merge, dedupe, enrich, or drop.
204→- An arc can have 1 moment (a standalone insight) or many (a full narrative thread).
205→- Total output moments should be <= total input moments.
206→
207→Respond with ONLY a JSON object: { "moments": [...] }`;
208→
209→  const user = `## Session Shape: ${sessionShape.shape}
210→## Total chunks: ${totalChunks}
211→
212→## Pass 1 Moments by Chunk:
213→
214→${pass1Moments
215→  .map(
216→    ({ chunkIndex, moments }) => `### Chunk ${chunkIndex} (${moments.length} moments):
217→${moments
218→  .map(
219→    (m, i) => `  ${i}. [${m.type}] ${m.statement}
220→     significance=${m.significance} agency=${m.agency} confidence=${m.confidence}
221→     topic=${m.topicFingerprint}
222→     evidence: ${m.evidence.map((e) => `"${e.quote.slice(0, 120)}"`).join("; ")}`,
223→  )
224→  .join("\n")}`,
225→  )
226→  .join("\n\n")}
227→
228→Synthesize these into final moments with arc assignments. Return JSON only.`;
229→
230→  return { system, user };
231→}
