 22→export async function runPipeline(logPath: string): Promise<{
 23→  sessionId: string;
 24→  narrative: SessionNarrative;
 25→  moments: SessionMoment[];
 26→  transitions: IntentTransition[];
 27→  outcomes: AcceptedOutcome[];
 28→}> {
 29→  // 1. Parse
 30→  log("[1/10] Parsing CC log...");
 31→  const rawEvents = await parseClaudeCodeLog(logPath);
 32→
 33→  // 2. Generate sessionId
 34→  const sessionId = crypto.randomUUID();
 35→
 36→  // 3. Normalize
 37→  log(`[2/10] Normalizing ${rawEvents.length} events...`);
 38→  const normalizedEvents = normalize(rawEvents, sessionId);
 39→
 40→  // Large session warning
 41→  if (normalizedEvents.length > 300) {
 42→    const estimatedChunks = Math.ceil(normalizedEvents.length / 60);
 43→    const estimatedLlmCalls = estimatedChunks + 3; // pass1 per chunk + classify + pass2 + transitions + narrative
 44→    log(
 45→      `  ⚠ Large session: ${normalizedEvents.length} events, ~${estimatedChunks} chunks, ~${estimatedLlmCalls} LLM calls`,
 46→    );
 47→  }
 48→
 49→  // 4. Analyze interactions
 50→  log("[3/10] Analyzing interactions...");
 51→  const directives = analyzeInteractions(normalizedEvents);
 52→
 53→  // 5. Classify
 54→  log("[4/10] Classifying session shape...");
 55→  const sessionShape = await classifySession(normalizedEvents);
 56→
 57→  // 6. Chunk
 58→  const sessionChunks = chunkSession(normalizedEvents, sessionId);
 59→  log(`[5/10] Chunking into ${sessionChunks.length} windows...`);
 60→
 61→  // 7. Detect moments (pass 1 + 2)
 62→  log("[6/10] Detecting moments (pass 1)...");
 63→  log("[7/10] Detecting moments (pass 2)...");
 64→  const sessionMoments = await detectMoments(sessionChunks, sessionShape, directives);
 65→
 66→  // 8. Transitions + outcomes
 67→  log("[8/10] Detecting transitions & outcomes...");
 68→  const { transitions, outcomes } = await detectTransitionsAndOutcomes(
 69→    sessionMoments,
 70→    sessionId,
 71→  );
 72→
 73→  // 9. Narrative
 74→  log("[9/10] Generating narrative...");
 75→  const narrative = await generateNarrative(
 76→    sessionMoments,
 77→    transitions,
 78→    outcomes,
 79→    sessionShape,
 80→  );
 81→  narrative.sessionId = sessionId;
 82→
 83→  // 10. Store
 84→  log("[10/10] Storing to database...");
 85→
 86→  // Derive timestamps from raw events
 87→  const timestamps = rawEvents
 88→    .map((e) => e.timestamp)
 89→    .filter(Boolean)
 90→    .map((t) => new Date(t));
 91→  const startedAt = timestamps.length > 0 ? new Date(Math.min(...timestamps.map((d) => d.getTime()))) : null;
 92→  const endedAt = timestamps.length > 0 ? new Date(Math.max(...timestamps.map((d) => d.getTime()))) : null;
 93→
 94→  try {
 95→    await storeSessionDigest({
 96→      sessionId,
 97→      sourceType: "claude-code",
 98→      sourcePath: logPath,
 99→      sessionShape,
100→      startedAt,
101→      endedAt,
102→      rawEvents,
103→      normalizedEvents,
104→      chunks: sessionChunks,
105→      moments: sessionMoments,
106→      transitions,
107→      outcomes,
108→      narrative,
109→    });
110→  } catch (err) {
111→    log(
112→      `  ⚠ Database write failed: ${err instanceof Error ? err.message : String(err)}`,
113→    );
114→    log("  Pipeline results are still available, just not persisted.");
115→  }
116→
117→  return {
118→    sessionId,
119→    narrative,
120→    moments: sessionMoments,
121→    transitions,
122→    outcomes,
123→  };
124→}
