13→/**
14→ * Classify a session's overall shape using Haiku.
15→ *
16→ * Builds a lightweight summary of the event stream and asks Haiku
17→ * to pick one of the five canonical session shapes.
18→ */
19→export async function classifySession(
20→  events: NormalizedDevEvent[],
21→): Promise<SessionShape> {
22→  const summary = buildSummary(events);
23→  const { system, user } = buildClassifyPrompt(summary);
24→  const result = await callHaiku(system, user, SessionShapeSchema);
25→  return result.shape as SessionShape;
26→}
27→
28→// ── Internal ──────────────────────────────────────────────────────────
29→
30→function buildSummary(events: NormalizedDevEvent[]): ClassifyInput {
31→  // Count events by category
32→  const eventCounts: Record<string, number> = {};
33→  for (const e of events) {
34→    eventCounts[e.category] = (eventCounts[e.category] ?? 0) + 1;
35→  }
36→
37→  // Count by actor
38→  for (const e of events) {
39→    const key = `actor:${e.actor}`;
40→    eventCounts[key] = (eventCounts[key] ?? 0) + 1;
41→  }
42→
43→  // Unique files touched
44→  const filesSet = new Set<string>();
45→  for (const e of events) {
46→    if (e.content.filesAffected) {
47→      for (const f of e.content.filesAffected) {
48→        filesSet.add(f);
49→      }
50→    }
51→  }
52→
53→  // Sample of first 3 user messages, truncated to 200 chars
54→  const userMessages: string[] = [];
55→  for (const e of events) {
56→    if (e.actor === "user" && e.category === "intent") {
57→      userMessages.push(e.content.summary.slice(0, 200));
58→      if (userMessages.length >= 3) break;
59→    }
60→  }
61→
62→  return {
63→    eventCounts,
64→    files: Array.from(filesSet),
65→    sampleUserMessages: userMessages,
66→    totalEvents: events.length,
67→  };
68→}
