 47→    arcRole: mapArcRoleBack(m.arcRole),
 48→    relatedMomentIds: m.relatedMomentIds.map((id) => {
 49→      const num = parseInt(id.replace("moment-", ""), 10);
 50→      return isNaN(num) ? 0 : num;
 51→    }),
 52→  }));
 53→
 54→  const promptTransitions: PromptTransition[] = transitions.map((t) => ({
 55→    fromStatement: t.fromStatement,
