 58→    triggeringMomentIndices: t.originMomentIds.map((id) => {
 59→      const num = parseInt(id.replace("moment-", ""), 10);
 60→      return isNaN(num) ? 0 : num;
 61→    }),
 62→    arcId: t.arcId ?? "",
 63→    confidence: t.confidence,
 64→  }));
 65→
 66→  const promptOutcomes: PromptOutcome[] = outcomes.map((o) => ({
