  1→import type {
  2→  NormalizedDevEvent,
  3→  TurnExchange,
  4→  PipelineDirectives,
  5→} from "../adapters/types.js";
  6→
  7→const REASONING_PATTERN =
  8→  /\b(because|actually|instead|but|however|rather)\b/i;
  9→
 10→const MULTIPLE_OPTIONS_PATTERN =
 11→  /[A-D]\)|option [A-D]|approach [A-D]/i;
 12→
 13→/**
 14→ * Analyze normalized events to produce pipeline directives.
 15→ *
 16→ * Groups events into turn exchanges (user message + following AI events),
 17→ * computes per-exchange interaction flags, and derives aggregate directives.
 18→ */
 19→export function analyzeInteractions(
 20→  events: NormalizedDevEvent[],
 21→): PipelineDirectives {
 22→  const exchanges = buildExchanges(events);
 23→  return computeDirectives(exchanges);
 24→}
 25→
 26→// ── Exchange Building ─────────────────────────────────────────────────
 27→
 28→/**
 29→ * Build turn exchanges by pairing each intent (user conversation_turn)
 30→ * with all following events until the next intent.
 31→ */
 32→function buildExchanges(events: NormalizedDevEvent[]): TurnExchange[] {
 33→  const exchanges: TurnExchange[] = [];
 34→
 35→  // Find all intent events (user messages)
 36→  const intentIndices: number[] = [];
 37→  for (let i = 0; i < events.length; i++) {
 38→    if (events[i].category === "intent") {
 39→      intentIndices.push(i);
 40→    }
 41→  }
 42→
 43→  for (let k = 0; k < intentIndices.length; k++) {
 44→    const devIdx = intentIndices[k];
 45→    const devEvent = events[devIdx];
 46→    const nextIntentIdx =
 47→      k + 1 < intentIndices.length ? intentIndices[k + 1] : events.length;
 48→
 49→    // AI turn events: everything between this intent and the next
 50→    const aiTurnEvents = events.slice(devIdx + 1, nextIntentIdx);
 51→
 52→    // Collect all AI text from the PREVIOUS AI turn (the one this dev event responds to)
 53→    // to check if it proposed multiple options
 54→    const previousAiText = getPreviousAiTurnText(events, devIdx);
 55→
 56→    const devDetail = devEvent.content.detail;
 57→    const devResponseChars = devDetail.length;
 58→    const devAskedQuestion = devDetail.includes("?");
 59→    const devUsedReasoning = REASONING_PATTERN.test(devDetail);
 60→
 61→    // Check if dev introduced a new topic by mentioning files not in prior AI turn
 62→    const devIntroducedNewTopic = checkNewTopic(devEvent, events, devIdx);
 63→
 64→    // Check if the prior AI proposed multiple options
 65→    const aiProposedMultipleOptions = MULTIPLE_OPTIONS_PATTERN.test(previousAiText);
 66→
 67→    // Check if dev responded to all proposed options
 68→    const devRespondedToAllOptions = aiProposedMultipleOptions
 69→      ? checkRespondedToAllOptions(devDetail, previousAiText)
 70→      : false;
 71→
 72→    exchanges.push({
 73→      devEvent,
 74→      aiTurnEvents,
 75→      devResponseChars,
 76→      devAskedQuestion,
 77→      devUsedReasoning,
 78→      devIntroducedNewTopic,
 79→      aiProposedMultipleOptions,
 80→      devRespondedToAllOptions,
 81→    });
 82→  }
 83→
 84→  return exchanges;
 85→}
 86→
 87→/**
 88→ * Get the combined text from the AI turn that precedes the given event index.
 89→ * This is the AI turn that the dev event is responding to.
 90→ */
 91→function getPreviousAiTurnText(
 92→  events: NormalizedDevEvent[],
 93→  devIdx: number,
 94→): string {
 95→  const devEvent = events[devIdx];
 96→
 97→  // Find the event this dev event is responding to
 98→  if (!devEvent.respondingTo) return "";
 99→
100→  const respondedEvent = events.find((e) => e.id === devEvent.respondingTo);
101→  if (!respondedEvent) return "";
102→
103→  // Get all events with the same turnId as the responded event
104→  const turnId = respondedEvent.turnId;
105→  const turnTexts: string[] = [];
106→  for (const e of events) {
107→    if (e.turnId === turnId && e.actor === "ai") {
108→      turnTexts.push(e.content.detail);
109→    }
110→  }
111→  return turnTexts.join("\n");
112→}
113→
114→/**
115→ * Check if the dev introduced a new topic not present in the prior AI context.
116→ * A new topic is detected when the dev mentions file paths or concepts
117→ * not in the AI turn's filesAffected.
118→ */
119→function checkNewTopic(
120→  devEvent: NormalizedDevEvent,
121→  events: NormalizedDevEvent[],
122→  devIdx: number,
123→): boolean {
124→  // First intent has no prior context — it establishes the topic
125→  if (devIdx === 0) return false;
126→  if (!devEvent.respondingTo) return false;
127→
128→  const respondedEvent = events.find((e) => e.id === devEvent.respondingTo);
129→  if (!respondedEvent) return false;
130→
131→  // Get all files from the prior AI turn
132→  const priorTurnId = respondedEvent.turnId;
133→  const priorFiles = new Set<string>();
134→  for (const e of events) {
135→    if (e.turnId === priorTurnId && e.content.filesAffected) {
136→      for (const f of e.content.filesAffected) {
137→        priorFiles.add(f);
138→      }
139→    }
140→  }
141→
142→  // Also collect files from the broader conversation up to this point
143→  const allPriorFiles = new Set<string>();
144→  for (let i = 0; i < devIdx; i++) {
145→    if (events[i].content.filesAffected) {
146→      for (const f of events[i].content.filesAffected) {
147→        allPriorFiles.add(f);
148→      }
149→    }
150→  }
151→
152→  // Check if dev message references concepts not in prior conversation
153→  // Heuristic: look for mentions of new technical concepts
154→  const devText = devEvent.content.detail.toLowerCase();
155→
156→  // Check for topic shift keywords (testing, deployment, etc.)
157→  // when the prior conversation was about something else
158→  const topicKeywords = ["test", "deploy", "migrate", "refactor", "debug", "performance", "security"];
159→  const priorTexts: string[] = [];
160→  for (let i = 0; i < devIdx; i++) {
161→    priorTexts.push(events[i].content.detail.toLowerCase());
162→  }
163→  const priorContext = priorTexts.join(" ");
164→
165→  for (const keyword of topicKeywords) {
166→    if (devText.includes(keyword) && !priorContext.includes(keyword)) {
167→      return true;
168→    }
169→  }
170→
171→  return false;
172→}
173→
174→/**
175→ * Check if the dev response addresses all proposed options.
176→ */
177→function checkRespondedToAllOptions(
178→  devText: string,
179→  aiText: string,
180→): boolean {
181→  // Find which options were proposed (A, B, C, D)
182→  const proposedOptions = new Set<string>();
183→  const optionPattern = /([A-D])\)|option ([A-D])|approach ([A-D])/gi;
184→  let match: RegExpExecArray | null;
185→  while ((match = optionPattern.exec(aiText)) !== null) {
186→    const letter = (match[1] || match[2] || match[3]).toUpperCase();
187→    proposedOptions.add(letter);
188→  }
189→
190→  if (proposedOptions.size <= 1) return true; // Only one option, trivially responded
191→
192→  // Check if dev response references multiple options
193→  const devUpper = devText.toUpperCase();
194→  let mentionedCount = 0;
195→  for (const option of proposedOptions) {
196→    if (devUpper.includes(option)) mentionedCount++;
197→  }
198→
199→  return mentionedCount >= proposedOptions.size;
200→}
