import { readFile, writeFile, mkdir } from 'fs/promises';
import { homedir } from 'os';
import { join } from 'path';

const LOG = join(homedir(), '.claude/projects/-Users-giladkoch-dev-intent-ai/84280b36-1375-4a79-9d53-e31c6d124146.jsonl');
const FIXTURES_DIR = join(process.cwd(), 'tests/eval/fixtures');

async function main() {
  await mkdir(FIXTURES_DIR, { recursive: true });

  const content = await readFile(LOG, 'utf-8');
  const lines = content.trim().split('\n');

  console.log(`Total lines: ${lines.length}`);

  // Parse timestamps to find scope boundaries
  const events = lines.map((line, i) => {
    try {
      const obj = JSON.parse(line);
      return { index: i, type: obj.type, timestamp: obj.timestamp, line };
    } catch { return { index: i, type: 'unknown', timestamp: '', line }; }
  });

  // Find user messages to identify phase boundaries
  const userMessages = events.filter(e => e.type === 'user').map(e => {
    try {
      const obj = JSON.parse(e.line);
      const content = obj.message?.content;
      const text = typeof content === 'string' ? content.slice(0, 100) : '[tool_result]';
      return { index: e.index, timestamp: e.timestamp, text };
    } catch { return { index: e.index, timestamp: e.timestamp, text: '?' }; }
  });

  console.log(`\nUser messages (${userMessages.length}):`);
  userMessages.forEach((m, i) => {
    console.log(`  ${i}. [line ${m.index}] ${m.text}`);
  });

  // Define scopes by line ranges
  // We need to identify the key phases:
  // Phase 1: PRD + brainstorming design (start → spec approved)
  // Phase 2: Implementation (scaffold through working digest)
  // Phase 3: Quality rejection + redesign (digest rejection → Layer 0)
  // Phase 4: Full session

  // Find key boundary events by searching for distinctive user messages
  const prdStart = 0;

  // Find "Spec and keep plan minimal" — marks end of design, start of implementation
  const specApprovalIdx = events.findIndex(e => {
    try {
      const obj = JSON.parse(e.line);
      if (obj.type === 'user' && typeof obj.message?.content === 'string') {
        return obj.message.content.includes('Spec and keep plan minimal');
      }
    } catch {}
    return false;
  });

  // Find "digest quality" discussion — marks the quality rejection
  const qualityRejectIdx = events.findIndex(e => {
    try {
      const obj = JSON.parse(e.line);
      if (obj.type === 'user' && typeof obj.message?.content === 'string') {
        return obj.message.content.includes('we lack actual worthwhile meaning');
      }
    } catch {}
    return false;
  });

  console.log(`\nPhase boundaries:`);
  console.log(`  PRD start: line 0`);
  console.log(`  Spec approval: line ${specApprovalIdx}`);
  console.log(`  Quality rejection: line ${qualityRejectIdx}`);
  console.log(`  Total lines: ${lines.length}`);

  // Create fixtures
  if (specApprovalIdx > 0) {
    // Scope 1: Design phase (PRD → spec approval)
    const designLines = lines.slice(0, specApprovalIdx + 10); // include a few after
    await writeFile(join(FIXTURES_DIR, 'scope-design.jsonl'), designLines.join('\n') + '\n');
    console.log(`\nScope: design — ${designLines.length} lines`);
  }

  if (specApprovalIdx > 0 && qualityRejectIdx > 0) {
    // Scope 2: Implementation phase (spec approval → quality rejection)
    const implLines = lines.slice(specApprovalIdx, qualityRejectIdx + 10);
    await writeFile(join(FIXTURES_DIR, 'scope-implementation.jsonl'), implLines.join('\n') + '\n');
    console.log(`Scope: implementation — ${implLines.length} lines`);
  }

  if (qualityRejectIdx > 0) {
    // Scope 3: Quality pivot (rejection → end)
    const pivotLines = lines.slice(qualityRejectIdx);
    await writeFile(join(FIXTURES_DIR, 'scope-pivot.jsonl'), pivotLines.join('\n') + '\n');
    console.log(`Scope: pivot — ${pivotLines.length} lines`);
  }

  // Scope 4: Full session
  await writeFile(join(FIXTURES_DIR, 'scope-full.jsonl'), content);
  console.log(`Scope: full — ${lines.length} lines`);

  console.log(`\nFixtures saved to ${FIXTURES_DIR}`);
}

main().catch(console.error);

